#!/usr/bin/env bash
# Reproduces the Competitive launch film b-roll (clips + stills) from public-domain
# sources on archive.org, so the repo carries no media binaries.
# Each clip is cut straight from its source URL with ffmpeg input seeking (HTTP range
# requests: only the needed seconds are transferred), deinterlaced/cropped, and
# re-encoded to H.264 with no audio. Rights for every item are in broll/credits.json.
#
# Every result is verified: its duration and two 8x6 luma fingerprints (near the first
# and last frame) must match the reviewed cut, because archive.org sometimes drops a
# connection mid-read or a seek in an MPEG-2 program stream lands on the wrong spot.
# Failed or mismatched cuts are retried.
#
# usage: broll/fetch.sh            kept clips + stills  -> .work/broll/{clips,stills}
#        ALTS=1 broll/fetch.sh     also the alternates   -> .work/broll/clips_alt
#        JOBS=4                    parallel cuts (default 3)
#        FORCE=1                   re-create files that already exist
#        OUT=/some/dir             output root (default: <project>/.work/broll)
# needs: bash, curl, ffmpeg/ffprobe (libx264), awk, od. Never disables TLS verification.
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="${OUT:-$ROOT/.work/broll}"
JOBS="${JOBS:-3}"
mkdir -p "$OUT/clips" "$OUT/stills"
[ "${ALTS:-0}" = 1 ] && mkdir -p "$OUT/clips_alt"
FAILLOG="$OUT/.fetch_failures"; : > "$FAILLOG"
NET=(-reconnect 1 -reconnect_on_network_error 1 -reconnect_delay_max 10 -rw_timeout 60000000)

sig() {   # 8x6 grey thumbnail of the frame at $2 s, as 48 dot-separated bytes
  ffmpeg -nostdin -v error -ss "$2" -i "$1" -frames:v 1 -vf scale=8:6:flags=area,format=gray \
    -f rawvideo - 2>/dev/null | od -An -v -tu1 | tr -s ' \n' '  ' | sed 's/^ *//; s/ *$//' | tr ' ' '.'
}
dist() {  # mean absolute difference of two signatures (999 if malformed)
  awk -v a="$1" -v b="$2" 'BEGIN{n=split(a,x,".");m=split(b,y,".");if(n!=48||m!=48){print 999;exit}
    s=0;for(i=1;i<=n;i++){d=x[i]-y[i];s+=(d<0?-d:d)};printf "%.1f",s/n}'
}
verify() {  # <file> <expected_duration> <sig_start> <sig_end>
  local d a b
  d=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$1" 2>/dev/null)
  awk -v d="$d" -v e="$2" 'BEGIN{exit !(d!="" && d-e<0.25 && e-d<0.25)}' || return 1
  a=$(dist "$(sig "$1" 0.3)" "$3")
  b=$(dist "$(sig "$1" "$(awk -v e="$2" 'BEGIN{printf "%.3f", e-0.3}')")" "$4")
  awk -v a="$a" -v b="$b" 'BEGIN{exit !(a<16 && b<8)}'
}

# clip <folder> <slug> <url> <in_s> <dur_s> <video_filter> <expected_dur> <sig_start> <sig_end>
clip() {
  local out="$OUT/$1/$2.mp4" tmp="$OUT/$1/.$2.tmp.mp4" n
  if [ -s "$out" ] && [ "${FORCE:-0}" != 1 ]; then echo "skip  $2"; return 0; fi
  for n in 1 2 3 4 5 6; do
    if ffmpeg -nostdin -hide_banner -loglevel error -y "${NET[@]}" -ss "$4" -i "$3" -t "$5" -an -sn -dn \
         -vf "$6" -c:v libx264 -preset slow -crf 16 -movflags +faststart "$tmp" 2>/dev/null \
       && verify "$tmp" "$7" "$8" "$9"; then
      mv "$tmp" "$out"; echo "ok    $2"; return 0
    fi
    echo "retry $2 ($n)" >&2; sleep $((n * 4))
  done
  rm -f "$tmp"; echo "FAIL  $2" >&2; echo "$2" >> "$FAILLOG"
}
run() { while [ "$(jobs -rp | wc -l)" -ge "$JOBS" ]; do wait -n; done; clip "$@" & }

still() {  # <slug> <url>
  local out="$OUT/stills/$1.jpg"
  if [ -s "$out" ] && [ "${FORCE:-0}" != 1 ]; then echo "skip  $1"; return 0; fi
  if curl -fsSL --retry 4 --retry-delay 5 -o "$out.tmp" "$2"; then mv "$out.tmp" "$out"; echo "ok    $1"
  else rm -f "$out.tmp"; echo "FAIL  $1" >&2; echo "$1" >> "$FAILLOG"; fi
}

